#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>
#include <climits>
using namespace std;

const int MAX_N = 20;
const int MAX_P = 400;
const int MAX_R = 200000;
const int INF_VAL = 199999999;

int grid[MAX_N][MAX_N];
int dist_src[MAX_P];
int spfa_q[MAX_P];
int in_spfa[MAX_P];
int dist_all[MAX_P][MAX_P];
int size_n, total_pts, time_max;
string line_data;
int src_row, src_col;
int rd[4] = {0, 0, -1, 1};
int cd[4] = {-1, 1, 0, 0};

struct FlowArc {
    int from, to, cap, link;
} arc[MAX_R];

int head[MAX_P], arc_idx;
int source_id, sink_id;
vector<int> source_points;
vector<int> dest_points;

inline int coord_to_id(int r, int c) {
    return (r-1) * size_n + c;
}

bool within_bounds(int r, int c) {
    return r >= 1 && r <= size_n && c >= 1 && c <= size_n && grid[r][c] != -1;
}

void construct_distance_graph() {
    total_pts = size_n * size_n;
    memset(dist_all, -1, sizeof(dist_all));
    for (int r = 1; r <= size_n; r++) {
        for (int c = 1; c <= size_n; c++) {
            if (grid[r][c] == -1) continue;
            int u = coord_to_id(r, c);
            dist_all[u][u] = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + rd[d];
                int nc = c + cd[d];
                if (within_bounds(nr, nc)) {
                    int v = coord_to_id(nr, nc);
                    dist_all[u][v] = 1;
                }
            }
        }
    }
}

void spfa_bfs() {
    for (int i = 1; i <= total_pts; i++) dist_src[i] = INF_VAL;
    int f = 0, r = 0;
    int start_id = coord_to_id(src_row, src_col);
    dist_src[start_id] = 0;
    spfa_q[r++] = start_id;
    while (f < r) {
        int u = spfa_q[f++];
        for (int v = 1; v <= total_pts; v++) {
            if (dist_all[u][v] == 1 && dist_src[v] > dist_src[u] + 1) {
                dist_src[v] = dist_src[u] + 1;
                spfa_q[r++] = v;
            }
        }
    }
}

void floyd_all_pairs() {
    for (int k = 1; k <= total_pts; k++) {
        for (int i = 1; i <= total_pts; i++) {
            for (int j = 1; j <= total_pts; j++) {
                if (dist_all[i][k] != -1 && dist_all[k][j] != -1) {
                    if (dist_all[i][j] == -1 || dist_all[i][j] > dist_all[i][k] + dist_all[k][j]) {
                        dist_all[i][j] = dist_all[i][k] + dist_all[k][j];
                    }
                }
            }
        }
    }
}

void build_flow_network() {
    memset(head, -1, sizeof(head));
    arc_idx = 0;
    source_id = 0;
    sink_id = source_points.size() / 3 + dest_points.size() / 3 + 1;

    for (size_t i = 0; i < source_points.size(); i += 3) {
        int cnt = source_points[i+2];
        arc[arc_idx] = {source_id, (int)(i/3)+1, cnt, head[source_id]};
        head[source_id] = arc_idx++;
        arc[arc_idx] = {(int)(i/3)+1, source_id, 0, head[(int)(i/3)+1]};
        head[(int)(i/3)+1] = arc_idx++;
    }

    for (size_t i = 0; i < dest_points.size(); i += 3) {
        int cnt = dest_points[i+2];
        arc[arc_idx] = {(int)(source_points.size()/3) + (int)(i/3)+1, sink_id, cnt, head[(int)(source_points.size()/3) + (int)(i/3)+1]};
        head[(int)(source_points.size()/3) + (int)(i/3)+1] = arc_idx++;
        arc[arc_idx] = {sink_id, (int)(source_points.size()/3) + (int)(i/3)+1, 0, head[sink_id]};
        head[sink_id] = arc_idx++;
    }

    int src_pos = coord_to_id(src_row, src_col);
    for (size_t i = 0; i < source_points.size(); i += 3) {
        int sr = source_points[i], sc = source_points[i+1];
        int sp = coord_to_id(sr, sc);
        for (size_t j = 0; j < dest_points.size(); j += 3) {
            int dr = dest_points[j], dc = dest_points[j+1];
            int dp = coord_to_id(dr, dc);
            if (dist_all[sp][dp] != -1 && dist_all[sp][dp] <= time_max) {
                if (dist_all[sp][dp] < dist_src[dp]) {
                    arc[arc_idx] = {(int)(i/3)+1, (int)(source_points.size()/3) + (int)(j/3)+1, INF_VAL, head[(int)(i/3)+1]};
                    head[(int)(i/3)+1] = arc_idx++;
                    arc[arc_idx] = {(int)(source_points.size()/3) + (int)(j/3)+1, (int)(i/3)+1, 0, head[(int)(source_points.size()/3) + (int)(j/3)+1]};
                    head[(int)(source_points.size()/3) + (int)(j/3)+1] = arc_idx++;
                } else if (dist_all[sp][dp] == dist_src[dp]) {
                    for (int d = 0; d < 4; ++d) {
                        int nr = dr + rd[d];
                        int nc = dc + cd[d];
                        if (within_bounds(nr, nc)) {
                            int np = coord_to_id(nr, nc);
                            if (dist_all[sp][np] == dist_all[sp][dp] - 1 && dist_all[sp][np] < dist_src[np]) {
                                arc[arc_idx] = {(int)(i/3)+1, (int)(source_points.size()/3) + (int)(j/3)+1, INF_VAL, head[(int)(i/3)+1]};
                                head[(int)(i/3)+1] = arc_idx++;
                                arc[arc_idx] = {(int)(source_points.size()/3) + (int)(j/3)+1, (int)(i/3)+1, 0, head[(int)(source_points.size()/3) + (int)(j/3)+1]};
                                head[(int)(source_points.size()/3) + (int)(j/3)+1] = arc_idx++;
                            }
                        }
                    }
                }
            }
        }
    }
}

int level_node[MAX_P];
int bfs_q2[MAX_P];

bool build_level_graph() {
    memset(level_node, -1, sizeof(level_node));
    int f = 0, r = 0;
    bfs_q2[r++] = source_id;
    level_node[source_id] = 0;
    while (f < r) {
        int u = bfs_q2[f++];
        for (int e = head[u]; e != -1; e = arc[e].link) {
            int v = arc[e].to;
            if (level_node[v] == -1 && arc[e].cap > 0) {
                level_node[v] = level_node[u] + 1;
                if (v == sink_id) return true;
                bfs_q2[r++] = v;
            }
        }
    }
    return false;
}

int dfs_path[MAX_P];
int curr_arc[MAX_P];

int dinic_dfs(int u, int flow) {
    if (u == sink_id) return flow;
    for (int &i = curr_arc[u]; i != -1; i = arc[i].link) {
        int v = arc[i].to;
        if (level_node[v] == level_node[u] + 1 && arc[i].cap > 0) {
            int push = dinic_dfs(v, min(flow, arc[i].cap));
            if (push > 0) {
                arc[i].cap -= push;
                arc[i ^ 1].cap += push;
                return push;
            }
        }
    }
    return 0;
}

int compute_max_flow() {
    int flow = 0;
    while (build_level_graph()) {
        for (int i = 0; i <= sink_id; i++) curr_arc[i] = head[i];
        while (int pushed = dinic_dfs(source_id, INF_VAL)) {
            flow += pushed;
        }
    }
    return flow;
}

int compute_result() {
    grid[src_row][src_col] = 0;
    construct_distance_graph();
    spfa_bfs();
    grid[src_row][src_col] = -1;
    construct_distance_graph();
    floyd_all_pairs();
    build_flow_network();
    return compute_max_flow();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> size_n >> time_max;
    source_points.clear();
    dest_points.clear();
    memset(grid, 0, sizeof(grid));

    for (int i = 1; i <= size_n; ++i) {
        cin >> line_data;
        for (int j = 0; j < size_n; ++j) {
            if (line_data[j] == 'Y') grid[i][j+1] = -1;
            else if (line_data[j] == 'Z') {
                src_row = i; src_col = j+1;
                grid[i][j+1] = -1;
            }
            else if (line_data[j] > '0' && line_data[j] <= '9') {
                source_points.push_back(i);
                source_points.push_back(j+1);
                source_points.push_back(line_data[j] - '0');
            }
        }
    }

    for (int i = 1; i <= size_n; ++i) {
        cin >> line_data;
        for (int j = 0; j < size_n; ++j) {
            if (line_data[j] > '0' && line_data[j] <= '9') {
                dest_points.push_back(i);
                dest_points.push_back(j+1);
                dest_points.push_back(line_data[j] - '0');
            }
        }
    }

    cout << compute_result() << '\n';
    return 0;
}
